package com.bastion.terminal.map

import com.bastion.terminal.nav.Nav
import java.util.Locale
import kotlin.math.abs
import kotlin.math.ceil
import kotlin.math.hypot
import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt

/**
 * Walking routes worked out from the shape of the ground — computed, never
 * generated by the AI model (same rule as [Nav]: a wrong bearing is worse
 * than none). Pure JVM.
 *
 * How: the elevation block is a grid; every step to a neighbouring cell costs
 * the time it takes to walk it (Tobler's hiking function: fastest on a gentle
 * downhill, slower the steeper it gets, up or down). Off a trail or road
 * walking is slower ([OFF_TRAIL]); very steep ground is slower still and
 * ground over [IMPASSABLE_DEG] is not crossed at all. The cheapest path
 * (A* search) is the route. It then is cut into a few straight legs a person
 * can follow with a compass: bearing, distance, climb.
 *
 * Limits, shown to the user: this knows slope and the trails in the pack. It
 * does not know rivers, cliffs smaller than a grid cell (~14 m), deadfall,
 * snow, private land or closures.
 */
object TerrainRoute {
    const val OFF_TRAIL = 0.6
    const val STEEP_DEG = 30f
    const val STEEP_FACTOR = 3.0
    const val IMPASSABLE_DEG = 40f
    private const val MAX_LEGS = 9

    data class Point(val lat: Double, val lon: Double, val elevation: Float)

    /** One straight stretch between two waypoints. */
    data class Leg(
        val from: Point, val to: Point,
        /** Compass bearing to hold, degrees true. */
        val bearing: Int,
        /** Straight-line distance between the waypoints, metres. */
        val meters: Double,
        val climbM: Int, val descentM: Int,
        /** Walking time for the path actually followed, seconds. */
        val seconds: Int,
        /** True when most of the leg runs along a trail or road in the pack. */
        val onTrail: Boolean,
    ) {
        fun text(n: Int): String {
            val updown = when {
                climbM >= 10 && descentM >= 10 -> ", up ${climbM} m, down ${descentM} m"
                climbM >= 10 -> ", up ${climbM} m"
                descentM >= 10 -> ", down ${descentM} m"
                else -> ", level"
            }
            return "$n. ${String.format(Locale.US, "%03d", bearing)}° ${Nav.compass(bearing)} for ${Nav.distanceText(meters)}" +
                updown + (if (onTrail) ", on trail" else "") + " (${timeText(seconds)})"
        }
    }

    data class Route(
        /** The full path, cell by cell. */
        val path: List<Point>,
        val legs: List<Leg>,
        /** Length of the path actually followed, metres. */
        val meters: Double,
        val climbM: Int, val descentM: Int, val seconds: Int,
    ) {
        fun summary(): String =
            "${Nav.distanceText(meters)}, about ${timeText(seconds)} on foot, up $climbM m, down $descentM m"
    }

    fun timeText(seconds: Int): String {
        val min = max(1, (seconds / 60.0).roundToInt())
        return if (min < 60) "$min min" else "${min / 60} h ${String.format(Locale.US, "%02d", min % 60)} min"
    }

    /**
     * Marks the cells that trails and roads pass through. [lines]: each a
     * list of world-fraction x,y pairs (x0,y0,x1,y1…) as held by MapPack.
     */
    fun trailMask(dem: Dem, lines: List<DoubleArray>): BooleanArray {
        val mask = BooleanArray(dem.w * dem.h)
        val worldPx = Geo.TILE.toDouble() * Geo.tilesAcross(dem.zoom)
        for (ln in lines) {
            var i = 0
            while (i + 3 < ln.size) {
                var ax = ln[i] * worldPx - dem.x0; var ay = ln[i + 1] * worldPx - dem.y0
                val bx = ln[i + 2] * worldPx - dem.x0; val by = ln[i + 3] * worldPx - dem.y0
                val steps = max(1, ceil(max(abs(bx - ax), abs(by - ay)) * 2).toInt())
                val dx = (bx - ax) / steps; val dy = (by - ay) / steps
                for (s in 0..steps) {
                    val cx = ax.toInt(); val cy = ay.toInt()
                    if (ax >= 0 && ay >= 0 && cx < dem.w && cy < dem.h) mask[cy * dem.w + cx] = true
                    ax += dx; ay += dy
                }
                i += 2
            }
        }
        return mask
    }

    /**
     * The quickest walking route from one position to another, or null if
     * either lies outside the elevation block or no passable route exists.
     * [trail]: cells with a trail or road ([trailMask]), or null for none.
     */
    fun route(dem: Dem, fromLat: Double, fromLon: Double, toLat: Double, toLon: Double, trail: BooleanArray? = null): Route? {
        if (!dem.contains(fromLat, fromLon) || !dem.contains(toLat, toLon)) return null
        val sx = dem.px(fromLon).toInt(); val sy = dem.py(fromLat).toInt()
        val ex = dem.px(toLon).toInt(); val ey = dem.py(toLat).toInt()
        // Search window: the two ends plus room to go around things. If nothing is found in
        // it (the way round a ridge can be far off to the side), the whole block is searched.
        val cell = dem.cellMeters((sy + ey) / 2)
        val pad = (max(750.0, 0.35 * hypot((ex - sx).toDouble(), (ey - sy).toDouble()) * cell) / cell).toInt()
        return search(dem, sx, sy, ex, ey, cell, pad, trail) ?: search(dem, sx, sy, ex, ey, cell, max(dem.w, dem.h), trail)
    }

    private fun search(dem: Dem, sx: Int, sy: Int, ex: Int, ey: Int, cell: Double, pad: Int, trail: BooleanArray?): Route? {
        val wx0 = max(0, min(sx, ex) - pad); val wy0 = max(0, min(sy, ey) - pad)
        val wx1 = min(dem.w - 1, max(sx, ex) + pad); val wy1 = min(dem.h - 1, max(sy, ey) + pad)
        val W = wx1 - wx0 + 1; val H = wy1 - wy0 + 1
        val n = W * H
        val start = (sy - wy0) * W + (sx - wx0); val goal = (ey - wy0) * W + (ex - wx0)

        // Per-cell slowdown from steepness; 0 = cannot be crossed. The two ends are always allowed.
        val factor = FloatArray(n)
        for (y in 0 until H) for (x in 0 until W) {
            val deg = dem.slopeDeg(x + wx0, y + wy0)
            val i = y * W + x
            val onTrail = trail != null && trail[(y + wy0) * dem.w + (x + wx0)]
            factor[i] = when {
                onTrail -> 1f // a built trail is walkable whatever the hillside does
                deg >= IMPASSABLE_DEG -> 0f
                deg >= STEEP_DEG -> (OFF_TRAIL / STEEP_FACTOR).toFloat()
                else -> OFF_TRAIL.toFloat()
            }
        }
        if (factor[start] == 0f) factor[start] = (OFF_TRAIL / STEEP_FACTOR).toFloat()
        if (factor[goal] == 0f) factor[goal] = (OFF_TRAIL / STEEP_FACTOR).toFloat()

        val best = FloatArray(n) { Float.MAX_VALUE }
        val prev = IntArray(n) { -1 }
        val done = BooleanArray(n)
        val heap = Heap(1024)
        val vmax = Geo.walkSpeed(-0.05, 1.0) // nothing is faster than the best case
        fun h(i: Int): Float {
            val dx = (i % W - goal % W).toDouble(); val dy = (i / W - goal / W).toDouble()
            return (hypot(dx, dy) * cell * 0.98 / vmax).toFloat()
        }
        best[start] = 0f
        heap.push(start, h(start))
        val DX = intArrayOf(1, -1, 0, 0, 1, 1, -1, -1); val DY = intArrayOf(0, 0, 1, -1, 1, -1, 1, -1)
        var found = false
        while (heap.size > 0) {
            val cur = heap.pop()
            if (done[cur]) continue
            done[cur] = true
            if (cur == goal) { found = true; break }
            val cx = cur % W; val cy = cur / W
            val ce = dem.at(cx + wx0, cy + wy0)
            for (k in 0 until 8) {
                val nx = cx + DX[k]; val ny = cy + DY[k]
                if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue
                val ni = ny * W + nx
                if (done[ni] || factor[ni] == 0f) continue
                val run = cell * (if (k < 4) 1.0 else 1.41421356)
                val rise = (dem.at(nx + wx0, ny + wy0) - ce).toDouble()
                val f = min(factor[cur], factor[ni])
                val t = best[cur] + (run / (Geo.walkSpeed(rise, run) * f)).toFloat()
                if (t < best[ni]) {
                    best[ni] = t; prev[ni] = cur
                    heap.push(ni, t + h(ni))
                }
            }
        }
        if (!found) return null

        val cells = ArrayList<Int>()
        var c = goal
        while (c != -1) { cells += c; c = prev[c] }
        cells.reverse()
        fun point(i: Int): Point {
            val gx = i % W + wx0; val gy = i / W + wy0
            return Point(dem.lat(gy + 0.5), dem.lon(gx + 0.5), dem.at(gx, gy))
        }
        val path = cells.map(::point)
        val onTrail = BooleanArray(cells.size) { j -> trail != null && trail[(cells[j] / W + wy0) * dem.w + (cells[j] % W + wx0)] }

        // Waypoints: the fewest straight legs that stay close to the path.
        val xs = DoubleArray(cells.size) { (cells[it] % W) * cell }; val ys = DoubleArray(cells.size) { (cells[it] / W) * cell }
        var tol = 60.0
        var keep = simplify(xs, ys, tol)
        while (keep.size - 1 > MAX_LEGS) { tol *= 1.5; keep = simplify(xs, ys, tol) }

        // Elevation is noisy cell to cell; count climb only in steps of 3 m or more.
        fun climbBetween(a: Int, b: Int): Pair<Int, Int> {
            var up = 0f; var down = 0f; var ref = path[a].elevation
            for (j in a + 1..b) {
                val d = path[j].elevation - ref
                if (d >= 3f) { up += d; ref = path[j].elevation } else if (d <= -3f) { down -= d; ref = path[j].elevation }
            }
            return up.roundToInt() to down.roundToInt()
        }
        fun pathMeters(a: Int, b: Int): Double {
            var m = 0.0
            for (j in a + 1..b) m += hypot(xs[j] - xs[j - 1], ys[j] - ys[j - 1])
            return m
        }
        val legs = keep.zipWithNext { a, b ->
            val p = path[a]; val q = path[b]
            val (up, down) = climbBetween(a, b)
            val trailShare = (a..b).count { onTrail[it] }.toDouble() / (b - a + 1)
            Leg(
                from = p, to = q,
                bearing = Nav.bearingDeg(p.lat, p.lon, q.lat, q.lon),
                meters = hypot(xs[b] - xs[a], ys[b] - ys[a]),
                climbM = up, descentM = down,
                seconds = (best[cells[b]] - best[cells[a]]).roundToInt(),
                onTrail = trailShare > 0.6,
            )
        }
        val (up, down) = climbBetween(0, path.size - 1)
        return Route(path, legs, pathMeters(0, path.size - 1), up, down, best[goal].roundToInt())
    }

    /** Douglas–Peucker: indexes of the points to keep so the line stays within [tol] metres of the path. */
    internal fun simplify(xs: DoubleArray, ys: DoubleArray, tol: Double): List<Int> {
        if (xs.size <= 2) return xs.indices.toList()
        val keep = BooleanArray(xs.size)
        keep[0] = true; keep[xs.size - 1] = true
        val stack = ArrayDeque<Pair<Int, Int>>()
        stack.addLast(0 to xs.size - 1)
        while (stack.isNotEmpty()) {
            val (a, b) = stack.removeLast()
            if (b - a < 2) continue
            val dx = xs[b] - xs[a]; val dy = ys[b] - ys[a]
            val len = hypot(dx, dy)
            var far = -1; var farD = tol
            for (i in a + 1 until b) {
                val d = if (len == 0.0) hypot(xs[i] - xs[a], ys[i] - ys[a])
                else abs(dy * (xs[i] - xs[a]) - dx * (ys[i] - ys[a])) / len
                if (d > farD) { farD = d; far = i }
            }
            if (far >= 0) { keep[far] = true; stack.addLast(a to far); stack.addLast(far to b) }
        }
        return xs.indices.filter { keep[it] }
    }

    /** Minimal binary min-heap of cell indexes keyed by a float. Duplicates are allowed. */
    private class Heap(capacity: Int) {
        private var ids = IntArray(capacity)
        private var keys = FloatArray(capacity)
        var size = 0
            private set

        fun push(id: Int, key: Float) {
            if (size == ids.size) { ids = ids.copyOf(size * 2); keys = keys.copyOf(size * 2) }
            var i = size++
            while (i > 0) {
                val p = (i - 1) / 2
                if (keys[p] <= key) break
                ids[i] = ids[p]; keys[i] = keys[p]; i = p
            }
            ids[i] = id; keys[i] = key
        }

        fun pop(): Int {
            val top = ids[0]
            size--
            if (size > 0) {
                val id = ids[size]; val key = keys[size]
                var i = 0
                while (true) {
                    var ch = 2 * i + 1
                    if (ch >= size) break
                    if (ch + 1 < size && keys[ch + 1] < keys[ch]) ch++
                    if (keys[ch] >= key) break
                    ids[i] = ids[ch]; keys[i] = keys[ch]; i = ch
                }
                ids[i] = id; keys[i] = key
            }
            return top
        }
    }
}
